    // 1. Null checks
    if ((vectors == NULL) || (weights == NULL) || (information == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Count range check [2, 32]
    if (count < 2 || count > 32) {
        return ADCS_E_RANGE;
    }

    // 3. Initialize output to zero (ensures "failure output zero")
    for (size_t i = 0; i < 3; ++i) {
        for (size_t j = 0; j < 3; ++j) {
            information->m[i][j] = 0.0;
        }
    }

    // 4. Validate weights are finite and positive
    for (size_t k = 0; k < count; ++k) {
        if (!isfinite(weights[k]) || weights[k] <= 0.0) {
            return ADCS_E_RANGE;
        }
    }

    // 5. Accumulate H = sum(w_k * (I - u_k * u_k^T))
    adcs_vec3_t uk;
    double outer[3][3];

    for (size_t k = 0; k < count; ++k) {
        // Normalize the observation vector
        if (adcs_vec3_normalize(&vectors[k], ADCS_EPS_NORM, &uk) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Compute outer product u_k * u_k^T
        outer[0][0] = uk.x * uk.x;
        outer[0][1] = uk.x * uk.y;
        outer[0][2] = uk.x * uk.z;
        outer[1][0] = uk.y * uk.x;
        outer[1][1] = uk.y * uk.y;
        outer[1][2] = uk.y * uk.z;
        outer[2][0] = uk.z * uk.x;
        outer[2][1] = uk.z * uk.y;
        outer[2][2] = uk.z * uk.z;

        double w = weights[k];

        // Add w_k * (I - outer) to H
        // Diagonal elements: I_ii is 1.0, Off-diagonal: I_ij is 0.0
        information->m[0][0] += w * (1.0 - outer[0][0]);
        information->m[0][1] += w * (0.0 - outer[0][1]);
        information->m[0][2] += w * (0.0 - outer[0][2]);

        information->m[1][0] += w * (0.0 - outer[1][0]);
        information->m[1][1] += w * (1.0 - outer[1][1]);
        information->m[1][2] += w * (0.0 - outer[1][2]);

        information->m[2][0] += w * (0.0 - outer[2][0]);
        information->m[2][1] += w * (0.0 - outer[2][1]);
        information->m[2][2] += w * (1.0 - outer[2][2]);
    }

    return ADCS_OK;
}

