    adcs_mat3_t h_acc;
    adcs_mat3_t i_mat;
    adcs_mat3_t outer;
    adcs_mat3_t neg_outer;
    adcs_mat3_t diff;
    adcs_mat3_t scaled;
    adcs_vec3_t u;
    size_t k;

    /* Boundary and failure handling: Null pointers */
    if ((vectors == NULL) || (weights == NULL) || (information == NULL)) {
        return ADCS_E_NULL;
    }

    /* Boundary and failure handling: Invalid count (2..32) */
    if (count < 2U || count > 32U) {
        return ADCS_E_RANGE;
    }

    /* Initialize output matrix to zero */
    for (size_t r = 0; r < 3; r++) {
        for (size_t c = 0; c < 3; c++) {
            information->m[r][c] = 0.0;
        }
    }

    /* Get Identity Matrix */
    i_mat = adcs_mat3_identity();

    /* Loop through all vectors and weights */
    for (k = 0; k < count; k++) {
        double w;

        /* Validate weight: finite and positive */
        if (!isfinite(weights[k]) || weights[k] <= 0.0) {
            return ADCS_E_RANGE;
        }
        w = weights[k];

        /* Normalize vector to get unit vector u_k */
        if (adcs_vec3_normalize(&vectors[k], ADCS_EPS_NORM, &u) != ADCS_OK) {
            /* Requirement: invalid vector -> ADCS_E_RANGE */
            return ADCS_E_RANGE;
        }

        /* Calculate outer product u_k * u_k^T */
        outer = adcs_mat3_outer(&u, &u);

        /* Calculate I - u_k * u_k^T */
        /* Since adcs_mat3_sub is not available, use add(I, scale(outer, -1.0)) */
        neg_outer = adcs_mat3_scale(outer, -1.0);
        diff = adcs_mat3_add(i_mat, neg_outer);

        /* Scale by weight w_k */
        scaled = adcs_mat3_scale(diff, w);

        /* Accumulate into H */
        *information = adcs_mat3_add(*information, scaled);
    }

    /* Output contract: Success */
    return ADCS_OK;
}

